package postgres
import("context";"testing";"time";"github.com/google/uuid";"github.com/menerjangbadai/dashboard/internal/application";"github.com/menerjangbadai/dashboard/internal/domain")
func TestRealSessionRevocationAndExpiry(t *testing.T){s:=testStore(t);ctx:=context.Background();sub:=uuid.NewString();a,e:=s.Bootstrap(ctx,"https://issuer.test/",sub,"Tester");if e!=nil{t.Fatal(e)};raw:=application.RandomToken();if e=s.CreateSession(ctx,application.Identity{Issuer:"https://issuer.test/",Subject:sub},application.Hash(raw),"");e!=nil{t.Fatal(e)};session,e:=s.Session(ctx,application.Hash(raw));if e!=nil||session.Actor.UserID!=a.UserID{t.Fatal(e)};if e=s.RevokeSession(ctx,application.Hash(raw));e!=nil{t.Fatal(e)};if _,e=s.Session(ctx,application.Hash(raw));e!=domain.ErrUnauthorized{t.Fatal("revoked valid",e)}
 if e=s.CreateSession(ctx,application.Identity{Issuer:"https://issuer.test/",Subject:uuid.NewString()},application.Hash(application.RandomToken()),"");e!=domain.ErrForbidden{t.Fatal("unprovisioned permitted",e)}
 if e=s.CreateSession(ctx,application.Identity{Issuer:"https://issuer.test/",Subject:sub},application.Hash(raw),"");e==nil{t.Fatal("reused session token allowed")}
 for _,column:=range []string{"idle_expires_at","absolute_expires_at"}{r:=application.Hash(application.RandomToken());if e=s.CreateSession(ctx,application.Identity{Issuer:"https://issuer.test/",Subject:sub},r,"");e!=nil{t.Fatal(e)};query:="UPDATE sessions SET idle_expires_at=now()-interval '1 second' WHERE token_hash=$1";if column=="absolute_expires_at"{query="UPDATE sessions SET idle_expires_at=now()-interval '1 second', absolute_expires_at=now()-interval '1 second' WHERE token_hash=$1"};_,e=s.Pool.Exec(ctx,query,r);if e!=nil{t.Fatal(e)};if _,e=s.Session(ctx,r);e!=domain.ErrUnauthorized{t.Fatalf("%s accepted: %v",column,e)}}
}
func TestRealLoginRequestSingleUseAndBrowserBinding(t *testing.T){s:=testStore(t);ctx:=context.Background();f:=application.LoginRequest{StateHash:application.Hash(application.RandomToken()),BindingHash:application.Hash("browser"),Nonce:"nonce",Verifier:"verifier",ExpiresAt:time.Now().Add(time.Minute)};if e:=s.SaveLogin(ctx,f);e!=nil{t.Fatal(e)};if _,e:=s.ConsumeLogin(ctx,f.StateHash,application.Hash("other"));e!=domain.ErrUnauthorized{t.Fatal(e)};if _,e:=s.ConsumeLogin(ctx,f.StateHash,f.BindingHash);e!=nil{t.Fatal(e)};if _,e:=s.ConsumeLogin(ctx,f.StateHash,f.BindingHash);e!=domain.ErrUnauthorized{t.Fatal("replayed",e)}}
